mapper.select:
SELECT rl.id AS rl_id, rl.ref_id AS rl_ref_id, rl.level AS rl_level,
       rl.min_value AS rl_min, rl.max_value AS rl_max
FROM apms_indicator_ref_level rl
JOIN apms_indicator_ref r ON rl.ref_id = r.id
WHERE r.indicator_id = #{indicatorId}
  AND r.gender       = #{gender}
  AND r.age_group    = #{ageGroup}
ORDER BY rl.min_value
